:root {
  --card-bg: #ffffff;
  --header-bg: #2d5a27;
  --header-text: #f0f7ee;
  --badge-bg: #a8d5a2;
  --badge-text: #1a3d16;
  --section-label: #5a7a55;
  --layer-moss-dot: #6ab04c;
  --layer-soil-dot: #8b5e3c;
  --layer-charcoal-dot: #4a4a4a;
  --layer-gravel-dot: #b0a090;
  --layer-name: #2e2e2e;
  --layer-tag-bg: #eef5ec;
  --layer-tag-text: #4a7a44;
  --plant-chip-bg: #f0f7ee;
  --plant-chip-border: #c5dfc2;
  --plant-chip-text: #2d5a27;
  --plant-chip-selected-bg: #2d5a27;
  --plant-chip-selected-text: #f0f7ee;
  --footer-border: #ddecd9;
  --price-label: #7a9a76;
  --price-value: #1a3d16;
  --btn-bg: #4caf50;
  --btn-text: #ffffff;
  --card-border: #d0e8cc;
  --divider: #e4f0e1;
}

.terrarium-card {
  background: var(--card-bg);
  border: 1.5px solid var(--card-border);
  border-radius: 14px;
  width: 460px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.card-header {
  background: var(--header-bg);
  padding: 12px 16px 10px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.badge {
  background: var(--badge-bg);
  color: var(--badge-text);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  padding: 2px 8px;
  border-radius: 20px;
  align-self: flex-start;
}

.card-title {
  color: var(--header-text);
  font-size: 18px;
  font-weight: 700;
  margin: 0;
  line-height: 1.2;
}

.card-body {
  display: flex;
  flex-direction: row;
  gap: 0;
}

.layers-section {
  padding: 10px 14px;
  flex: 1;
  border-right: 1.5px solid var(--divider);
}

.plants-section {
  padding: 10px 14px;
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.section-label {
  color: var(--section-label);
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.07em;
  margin: 0 0 7px;
}

.layer-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.layer {
  display: flex;
  align-items: center;
  gap: 7px;
}

.layer-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  flex-shrink: 0;
}

[data-layer="moss"] .layer-dot { background: var(--layer-moss-dot); }
[data-layer="soil"] .layer-dot { background: var(--layer-soil-dot); }
[data-layer="charcoal"] .layer-dot { background: var(--layer-charcoal-dot); }
[data-layer="gravel"] .layer-dot { background: var(--layer-gravel-dot); }

.layer-name {
  color: var(--layer-name);
  font-size: 12px;
  flex: 1;
}

.layer-tag {
  background: var(--layer-tag-bg);
  color: var(--layer-tag-text);
  font-size: 10px;
  font-weight: 600;
  padding: 1px 6px;
  border-radius: 8px;
}

.plant-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 5px;
}

.plant-chip {
  background: var(--plant-chip-bg);
  border: 1.5px solid var(--plant-chip-border);
  color: var(--plant-chip-text);
  font-size: 11px;
  font-weight: 500;
  padding: 5px 6px;
  border-radius: 7px;
  text-align: center;
}

.plant-chip.selected {
  background: var(--plant-chip-selected-bg);
  color: var(--plant-chip-selected-text);
  border-color: var(--plant-chip-selected-bg);
}

.card-footer {
  border-top: 1.5px solid var(--footer-border);
  padding-top: 8px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: auto;
}

.price-block {
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.price-label {
  color: var(--price-label);
  font-size: 10px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.price-value {
  color: var(--price-value);
  font-size: 18px;
  font-weight: 800;
  line-height: 1;
}

.enroll-btn {
  background: var(--btn-bg);
  color: var(--btn-text);
  font-size: 12px;
  font-weight: 700;
  border: none;
  border-radius: 8px;
  padding: 7px 14px;
  cursor: pointer;
}
